"""Record layouts for inventory. Generated by Séance from the COBOL record descriptions. Do not edit."""

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal

from seance.cobol_num import deedit, format_alpha, format_edited, format_numeric, parse_numeric

IN_WIDTH = 29
OUT_WIDTH = 19


@dataclass
class InRecord:
    sku: str
    on_hand: Decimal
    received: Decimal
    shipped: Decimal
    reorder: Decimal

    @classmethod
    def parse(cls, line: str) -> "InRecord":
        line = line.ljust(29)
        return cls(
            sku=line[0:8].rstrip(),
            on_hand=parse_numeric(line[8:14], 5, 0, True, 'leading_sep'),
            received=parse_numeric(line[14:19], 5, 0, False, 'none'),
            shipped=parse_numeric(line[19:24], 5, 0, False, 'none'),
            reorder=parse_numeric(line[24:29], 5, 0, False, 'none'),
        )

    def format(self) -> str:
        return (
            format_alpha(self.sku, 8)
            + format_numeric(self.on_hand, 5, 0, True, 'leading_sep')
            + format_numeric(self.received, 5, 0, False, 'none')
            + format_numeric(self.shipped, 5, 0, False, 'none')
            + format_numeric(self.reorder, 5, 0, False, 'none')
        ).rstrip()


@dataclass
class OutRecord:
    sku: str
    new_on_hand: Decimal
    backorder: Decimal
    flag: str

    @classmethod
    def parse(cls, line: str) -> "OutRecord":
        line = line.ljust(19)
        return cls(
            sku=line[0:8].rstrip(),
            new_on_hand=parse_numeric(line[8:13], 5, 0, False, 'none'),
            backorder=parse_numeric(line[13:18], 5, 0, False, 'none'),
            flag=line[18:19].rstrip(),
        )

    def format(self) -> str:
        return (
            format_alpha(self.sku, 8)
            + format_numeric(self.new_on_hand, 5, 0, False, 'none')
            + format_numeric(self.backorder, 5, 0, False, 'none')
            + format_alpha(self.flag, 1)
        ).rstrip()

